import{_ as e,o as n,c as s,a2 as t}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Engineering Delivery and Repository Structure","description":"Hearth's engineering principles, tech stack, repository layout, process model, data directories, CLI, testing, observability, and release migration.","frontmatter":{"title":"Engineering Delivery and Repository Structure","description":"Hearth's engineering principles, tech stack, repository layout, process model, data directories, CLI, testing, observability, and release migration.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/engineering.md","filePath":"en/delivery/engineering.md","lastUpdated":1793706118000}`),i={name:"en/delivery/engineering.md"};function r(o,a,l,p,c,d){return n(),s("div",null,[...a[0]||(a[0]=[t(`<p class="eyebrow">ENGINEERING</p><h1 id="engineering-delivery-and-repository-structure" tabindex="-1">Engineering Delivery and Repository Structure <a class="header-anchor" href="#engineering-delivery-and-repository-structure" aria-label="Permalink to &quot;Engineering Delivery and Repository Structure&quot;">​</a></h1><p class="lead">Engineering principles, recommended tech stack, repository layout, process model, data directory, CLI, Event Log, testing, observability, and release migration.</p><h2 id="engineering-architecture-and-repository-structure" tabindex="-1">Engineering Architecture and Repository Structure <a class="header-anchor" href="#engineering-architecture-and-repository-structure" aria-label="Permalink to &quot;Engineering Architecture and Repository Structure&quot;">​</a></h2><h3 id="engineering-principles" tabindex="-1">Engineering Principles <a class="header-anchor" href="#engineering-principles" aria-label="Permalink to &quot;Engineering Principles&quot;">​</a></h3><ul><li><strong>Modular monolith first</strong>: do not introduce microservices early;</li><li><strong>Vertical slices first</strong>: every milestone must simultaneously include UI, persistent state, execution, verification, and recovery;</li><li><strong>The interface is the acceptance surface</strong>: capabilities that users cannot complete in the browser do not pass the stage exit;</li><li><strong>Single writer</strong>: the same State Root has only one write authority;</li><li><strong>Event sourcing</strong>: facts are written to the Event Log; UI/indexes are projections;</li><li><strong>Schema first</strong>: inputs, outputs, Effects, and Approvals all have versioned schemas;</li><li><strong>Adapter isolation</strong>: Codex, Connector, Browser, GUI, and Sandbox are all integrated through interfaces;</li><li><strong>Local first</strong>: data is local by default, and cloud resources are replaceable;</li><li><strong>Rollback-capable</strong>: databases, skills, configuration, and releases all have rollback paths;</li><li><strong>Observable</strong>: every task has a correlation id, trace, and cost attribution.</li></ul><h3 id="recommended-tech-stack" tabindex="-1">Recommended Tech Stack <a class="header-anchor" href="#recommended-tech-stack" aria-label="Permalink to &quot;Recommended Tech Stack&quot;">​</a></h3><p>The following are default recommendations, not an unchangeable religion:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Recommendation</th></tr></thead><tbody><tr><td>Language</td><td>TypeScript / Node.js 22+</td></tr><tr><td>Package management</td><td>pnpm</td></tr><tr><td>Monorepo</td><td>Turborepo or equivalent tooling</td></tr><tr><td>Long-running service</td><td>Node + Fastify/Hono</td></tr><tr><td>Database</td><td>SQLite WAL + migration</td></tr><tr><td>Schema</td><td>Zod / JSON Schema</td></tr><tr><td>Web</td><td>React + Vite + PWA</td></tr><tr><td>Real-time updates</td><td>SSE first, WebSocket when necessary</td></tr><tr><td>Browser</td><td>Playwright</td></tr><tr><td>Documents/data</td><td>Python sidecar + mature parsing libraries</td></tr><tr><td>Sandbox</td><td>Start with Docker, microVMs for untrusted tasks</td></tr><tr><td>Observability</td><td>OpenTelemetry + local logs/metrics</td></tr><tr><td>Testing</td><td>Vitest/Playwright/contract testing/fault injection</td></tr><tr><td>Packaging</td><td>npm CLI + Docker Compose</td></tr></tbody></table><p>The reason for choosing TypeScript is that the frontend and backend share types, event protocols, and schemas, making it suitable for rapidly building a local Web and CLI; document/data-intensive processing is supplemented by a Python sidecar to fill in the ecosystem, without splitting the entire system into multilingual microservices.</p><h3 id="repository-layout" tabindex="-1">Repository Layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository Layout&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth-os/</span></span>
<span class="line"><span>  apps/</span></span>
<span class="line"><span>    hearthd/              # Resident service: Gateway / Control / Harness</span></span>
<span class="line"><span>    web/                  # Task cards, approvals, artifacts, PWA</span></span>
<span class="line"><span>    cli/                  # hearth commands</span></span>
<span class="line"><span>    agentd/               # Device node (later)</span></span>
<span class="line"><span>  packages/</span></span>
<span class="line"><span>    core/                 # Domain model, state machine, error classification</span></span>
<span class="line"><span>    eventlog/             # Event Log, projections, migration</span></span>
<span class="line"><span>    harness/              # Ticket, Run, lease, outbox, recovery</span></span>
<span class="line"><span>    policy/               # Policy, Mandate, Capability, risk</span></span>
<span class="line"><span>    context/              # Context Compiler, Task Pack</span></span>
<span class="line"><span>    token/                # Token Governor, budget, attribution</span></span>
<span class="line"><span>    memory/               # Memory writes, retrieval, forgetting, sync</span></span>
<span class="line"><span>    evolution/            # Trajectories, skills, evaluation, promotion, rollback</span></span>
<span class="line"><span>    executors/</span></span>
<span class="line"><span>      native/</span></span>
<span class="line"><span>      codex/</span></span>
<span class="line"><span>      connector/</span></span>
<span class="line"><span>      browser/</span></span>
<span class="line"><span>      gui/</span></span>
<span class="line"><span>      document/</span></span>
<span class="line"><span>    connectors/           # email/calendar/docs/im/issue</span></span>
<span class="line"><span>    gateway/              # Channels, devices, notifications, identity</span></span>
<span class="line"><span>    execution/            # Sandbox Provider, egress, Broker</span></span>
<span class="line"><span>    artifacts/            # Artifacts, hashes, versions, verification</span></span>
<span class="line"><span>    evals/                # Task sets, runner, scorer</span></span>
<span class="line"><span>    shared/               # schema, types, utilities</span></span>
<span class="line"><span>  sidecars/</span></span>
<span class="line"><span>    docdata/              # Python document/data pipeline</span></span>
<span class="line"><span>  fixtures/</span></span>
<span class="line"><span>  docs/</span></span>
<span class="line"><span>    adr/</span></span>
<span class="line"><span>    architecture/</span></span>
<span class="line"><span>  docker/</span></span></code></pre></div><h3 id="process-model" tabindex="-1">Process Model <a class="header-anchor" href="#process-model" aria-label="Permalink to &quot;Process Model&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth CLI / Web / Mobile</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>       hearthd</span></span>
<span class="line"><span>  ├─ Gateway</span></span>
<span class="line"><span>  ├─ Control Plane</span></span>
<span class="line"><span>  ├─ Durable Harness</span></span>
<span class="line"><span>  ├─ Token Governor / Context Compiler</span></span>
<span class="line"><span>  ├─ Executor Supervisor</span></span>
<span class="line"><span>  ├─ Event Log / projections</span></span>
<span class="line"><span>  ├─ Sandbox Provider client</span></span>
<span class="line"><span>  ├─ Credential Broker</span></span>
<span class="line"><span>  └─ Effect Dispatcher</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ├─ Codex adapter</span></span>
<span class="line"><span>          ├─ Browser worker</span></span>
<span class="line"><span>          ├─ Connector workers</span></span>
<span class="line"><span>          ├─ Document/Data sidecar</span></span>
<span class="line"><span>          └─ Device agentd (later)</span></span></code></pre></div><p>All Executors connect through a unified protocol and never write directly to the primary database. SQLite is written by the single <code>hearthd</code> process; Executors receive work through RPC/Task queues.</p><h3 id="data-directory" tabindex="-1">Data Directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data Directory&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.hearth/</span></span>
<span class="line"><span>  state.db                # Event Log + projections</span></span>
<span class="line"><span>  artifacts/              # Content-addressed artifacts</span></span>
<span class="line"><span>  workspaces/             # Temporary and project workspaces</span></span>
<span class="line"><span>  config/</span></span>
<span class="line"><span>    policy.yaml</span></span>
<span class="line"><span>    connections.yaml</span></span>
<span class="line"><span>  secrets/                # Encrypted credentials or Broker pointers</span></span>
<span class="line"><span>  logs/</span></span>
<span class="line"><span>  backups/</span></span>
<span class="line"><span>  devices/</span></span></code></pre></div><p>Minimize permissions on sensitive directories; encrypt backups; device sync transmits only the necessary projections and Artifact references.</p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth init</span></span>
<span class="line"><span>hearth run &quot;compile this week&#39;s competitor updates and generate a weekly report draft&quot;</span></span>
<span class="line"><span>hearth status</span></span>
<span class="line"><span>hearth inbox</span></span>
<span class="line"><span>hearth approve &lt;id&gt;</span></span>
<span class="line"><span>hearth artifacts</span></span>
<span class="line"><span>hearth memory search &quot;Project A decisions&quot;</span></span>
<span class="line"><span>hearth memory forget &lt;id&gt;</span></span>
<span class="line"><span>hearth doctor</span></span>
<span class="line"><span>hearth export</span></span></code></pre></div><p>CLI output supports both human-readable and JSON modes, making it convenient for scripts and automated tests.</p><h3 id="event-log-and-projections" tabindex="-1">Event Log and Projections <a class="header-anchor" href="#event-log-and-projections" aria-label="Permalink to &quot;Event Log and Projections&quot;">​</a></h3><ul><li>Events are append-only and are not updated in place;</li><li>Each Event has schemaVersion, correlationId, and causationId;</li><li>Task state, inbox, Artifacts, and costs are all projections;</li><li>Projections can be rebuilt;</li><li>Event hash chains or equivalent integrity verification;</li><li>Large content is stored in Artifacts, and Events store only references;</li><li>Migrations must remain compatible with old Events;</li><li>Event replay must not produce external side effects.</li></ul><h3 id="tasks-and-leases" tabindex="-1">Tasks and Leases <a class="header-anchor" href="#tasks-and-leases" aria-label="Permalink to &quot;Tasks and Leases&quot;">​</a></h3><ul><li>Each Ticket has at most one active Assignment at any given time;</li><li>Leases carry a fencing token;</li><li>Executors validate the fencing token before writing;</li><li>When a device goes offline, its lease expires and the Task can be reassigned;</li><li>Reassignment must not duplicate external Effects;</li><li>Task state transitions have explicit Events and conditions;</li><li>Subtasks inherit the parent Task&#39;s budget and permission intersection.</li></ul><h3 id="testing-strategy" tabindex="-1">Testing Strategy <a class="header-anchor" href="#testing-strategy" aria-label="Permalink to &quot;Testing Strategy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Content</th></tr></thead><tbody><tr><td>Unit</td><td>schema, policies, validators, cost calculation</td></tr><tr><td>Contract</td><td>Executor, Connector, Sandbox, Broker</td></tr><tr><td>Integration</td><td>Event Log, outbox, lease, recovery</td></tr><tr><td>E2E</td><td>Task cards, approvals, Artifacts, email drafts</td></tr><tr><td>Slice E2E</td><td>browser path from Task creation to Artifacts/recovery for each increment</td></tr><tr><td>Fault Injection</td><td>crashes, network disconnection, timeouts, duplication, full disk</td></tr><tr><td>Replay</td><td>historical trace replay, route switching</td></tr><tr><td>Security</td><td>injection, privilege escalation, secrets, sandbox, egress</td></tr><tr><td>Performance</td><td>startup, queries, long-running Tasks, concurrency limits</td></tr></tbody></table><h3 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h3><ul><li>Each Task/Run has a trace id;</li><li>Each model call records the model, tokens, cost, and latency;</li><li>Each tool call records the parameter hash, result status, and resources;</li><li>Each external side effect records an idempotency key and a Receipt;</li><li>The UI displays only the Events that users need;</li><li>Detailed information is retained in a local audit view;</li><li>Logs are automatically redacted;</li><li>Metrics are used for routing and evaluation, not for manipulating users.</li></ul><h3 id="release-and-migration" tabindex="-1">Release and Migration <a class="header-anchor" href="#release-and-migration" aria-label="Permalink to &quot;Release and Migration&quot;">​</a></h3><ul><li>Version schemas and APIs;</li><li>Database migrations are forward-compatible;</li><li>Executor versions are pinned;</li><li>Skills are versioned;</li><li>Run evaluations and fault injection before release;</li><li>Support rollback to the previous stable version;</li><li>Upgrades do not break historical Events and Artifacts;</li><li>Users can export and migrate.</li><li>Each increment retains a rollback-capable version; recovery must not rely solely on rebuilding the environment.</li></ul><hr>`,32)])])}const g=e(i,[["render",r]]);export{u as __pageData,g as default};
